// This file is generated by AI.

// 目录浏览组件: 每次只打开一层目录 (文件夹 + 文件), 不递归扫描子目录。
// 进入子目录后才扫描该层; 支持返回上级、在当前目录内搜索、展平当前目录。

import { ArrowUpRegular, MoreVerticalRegular } from '@fluentui/react-icons';
import { useEffect, useRef, useState, type ReactNode } from 'react';

import { fs } from '../lib/fs';

export type FileKind = 'image' | 'audio' | 'video' | 'text' | 'scene' | 'other';

export interface FileNode {
  name: string;
  path: string;
  rel: string;
  isDirectory: boolean;
  kind: FileKind;
}

const IMAGE_EXT = ['png', 'jpg', 'jpeg', 'gif', 'webp', 'bmp', 'svg'];
const AUDIO_EXT = ['mp3', 'ogg', 'wav', 'flac', 'm4a', 'aac'];
const VIDEO_EXT = ['mp4', 'webm', 'ogv', 'mov'];
const TEXT_EXT = ['txt', 'json', 'js', 'css', 'html', 'csv', 'md', 'ts'];

export function kindFor(name: string): FileKind {
  const i = name.lastIndexOf('.');
  const e = i < 0 ? '' : name.slice(i + 1).toLowerCase();
  if (IMAGE_EXT.includes(e)) return 'image';
  if (AUDIO_EXT.includes(e)) return 'audio';
  if (VIDEO_EXT.includes(e)) return 'video';
  if (TEXT_EXT.includes(e)) return 'text';
  return 'other';
}

/** 长名称中间省略: 保留开头与扩展名后缀。 */
export function middleEllipsis(text: string, maxLen: number): string {
  if (text.length <= maxLen) return text;
  const dot = text.lastIndexOf('.');
  const hasExt = dot > 0 && dot < text.length - 1;
  const ext = hasExt ? text.slice(dot) : '';
  const stem = hasExt ? text.slice(0, dot) : text;
  const avail = maxLen - ext.length - 3; // 3 = "..."
  if (avail < 4) return `${text.slice(0, Math.max(1, maxLen - 3))}...`;
  const keepHead = Math.ceil(avail / 2);
  const keepTail = avail - keepHead;
  return `${stem.slice(0, keepHead)}...${stem.slice(stem.length - keepTail)}${ext}`;
}

export const KIND_BADGE: Record<FileKind, string> = {
  image: 'IMG',
  audio: '♪',
  video: '▶',
  text: 'TXT',
  scene: 'SCN',
  other: '?',
};

async function recursiveFiles(dir: string, baseRel: string): Promise<FileNode[]> {
  const result: FileNode[] = [];
  async function walk(d: string, rel: string): Promise<void> {
    let entries: { name: string; isDirectory: boolean }[];
    try {
      entries = await fs.readDir(d);
    } catch {
      return;
    }
    entries.sort((a, b) => a.name.localeCompare(b.name));
    for (const e of entries) {
      const full = `${d}\\${e.name}`;
      const childRel = rel ? `${rel}/${e.name}` : e.name;
      if (e.isDirectory) {
        await walk(full, childRel);
      } else {
        result.push({ name: e.name, path: full, rel: childRel, isDirectory: false, kind: kindFor(e.name) });
      }
    }
  }
  await walk(dir, baseRel);
  return result;
}

export interface ToolbarMenuItem {
  key: string;
  label: string;
  icon?: ReactNode;
  danger?: boolean;
  onClick: () => void;
}

interface FileTreeProps {
  rootPath: string;
  onOpen: (file: FileNode) => void;
  selectedPath?: string | null;
  excludeTop?: (name: string) => boolean;
  assetUrl?: (rel: string) => string | undefined;
  /** 内容变更 (新建/重命名/删除) 后递增, 强制重新加载当前目录 */
  refreshKey?: number;
  /** 工具栏右侧下拉菜单项 (返回上级按钮与展平按钮独立保留在工具栏上) */
  menu?: (currentDir: string) => ToolbarMenuItem[];
  /** 列表项右键菜单回调 (文件与文件夹均触发) */
  onItemContextMenu?: (node: FileNode, e: React.MouseEvent) => void;
  /** 文件行右侧附加徽标 (如 git 更改类型 / 诊断数) */
  badge?: (node: FileNode) => ReactNode;
  /** 自定义工具栏与列表的摆放方式; 缺省时工具栏在列表上方 (上下堆叠) */
  header?: (toolbar: ReactNode, list: ReactNode) => ReactNode;
}

export function FileTree({
  rootPath,
  onOpen,
  selectedPath,
  excludeTop,
  assetUrl,
  refreshKey = 0,
  menu,
  onItemContextMenu,
  badge,
  header,
}: FileTreeProps) {
  const [currentRel, setCurrentRel] = useState('');
  const [dirEntries, setDirEntries] = useState<FileNode[]>([]);
  const [query, setQuery] = useState('');
  const [flat, setFlat] = useState(false);
  const [flatEntries, setFlatEntries] = useState<FileNode[] | null>(null);
  const [searchResults, setSearchResults] = useState<FileNode[] | null>(null);

  const currentAbs = currentRel ? `${rootPath}\\${currentRel.replace(/\//g, '\\')}` : rootPath;

  // 加载当前单层目录
  useEffect(() => {
    let cancelled = false;
    (async () => {
      let entries: { name: string; isDirectory: boolean }[];
      try {
        entries = await fs.readDir(currentAbs);
      } catch {
        entries = [];
      }
      if (cancelled) return;
      entries.sort((a, b) => (a.isDirectory === b.isDirectory ? a.name.localeCompare(b.name) : a.isDirectory ? -1 : 1));
      setDirEntries(
        entries
          .filter((e) => !(currentRel === '' && excludeTop && excludeTop(e.name)))
          .map((e) => ({
            name: e.name,
            path: `${currentAbs}\\${e.name}`,
            rel: currentRel ? `${currentRel}/${e.name}` : e.name,
            isDirectory: e.isDirectory,
            kind: e.isDirectory ? 'other' : kindFor(e.name),
          }))
      );
    })();
    return () => {
      cancelled = true;
    };
  }, [currentAbs, excludeTop, refreshKey]);

  // 展平: 递归列出当前目录下所有文件
  useEffect(() => {
    if (!flat) {
      setFlatEntries(null);
      return;
    }
    let cancelled = false;
    void recursiveFiles(currentAbs, currentRel).then((files) => {
      if (!cancelled) setFlatEntries(files);
    });
    return () => {
      cancelled = true;
    };
  }, [flat, currentAbs, currentRel, refreshKey]);

  // 搜索: 在当前目录内递归过滤文件
  useEffect(() => {
    const q = query.trim().toLowerCase();
    if (!q) {
      setSearchResults(null);
      return;
    }
    let cancelled = false;
    void recursiveFiles(currentAbs, currentRel).then((files) => {
      if (!cancelled) {
        setSearchResults(files.filter((f) => f.name.toLowerCase().includes(q) || f.rel.toLowerCase().includes(q)));
      }
    });
    return () => {
      cancelled = true;
    };
  }, [query, currentAbs, currentRel, refreshKey]);

  const resetView = () => {
    setQuery('');
    setFlat(false);
  };

  const enterDir = (name: string) => {
    setCurrentRel((prev) => (prev ? `${prev}/${name}` : name));
    resetView();
  };

  const goUp = () => {
    setCurrentRel((prev) => (prev.includes('/') ? prev.slice(0, prev.lastIndexOf('/')) : ''));
    resetView();
  };

  // 展示列表: 搜索结果 > 展平结果 > 单层目录
  let list: FileNode[];
  let showPath = false;
  if (searchResults) {
    list = searchResults;
    showPath = true;
  } else if (flatEntries) {
    list = flatEntries;
    showPath = true;
  } else {
    list = dirEntries;
  }

  // 展平/搜索时展示"从当前位置出发"的相对路径 (去掉从根到当前目录的前缀)
  const displayRel = (node: FileNode): string => {
    const base = currentRel ? `${currentRel}/` : '';
    return node.rel.startsWith(base) ? node.rel.slice(base.length) : node.rel;
  };

  const fileRow = (node: FileNode) => {
    const displayText = showPath ? displayRel(node) : node.name;
    return (
      <button
        key={node.path}
        className={`file-tree-file${node.path === selectedPath ? ' active' : ''}`}
        onClick={() => onOpen(node)}
        onContextMenu={(e) => onItemContextMenu?.(node, e)}
        title={node.rel}
      >
        {node.kind === 'image' && assetUrl ? (
          <img className="resource-thumb" src={assetUrl(node.rel)} alt="" loading="lazy" />
        ) : (
          <span className="resource-badge">{KIND_BADGE[node.kind]}</span>
        )}
        <span className="resource-name" title={displayText}>
          {middleEllipsis(displayText, 30)}
        </span>
        {badge ? badge(node) : null}
      </button>
    );
  };

  const [menuOpen, setMenuOpen] = useState(false);
  const menuBtnRef = useRef<HTMLButtonElement>(null);
  const [menuPos, setMenuPos] = useState<{ x: number; y: number } | null>(null);

  // 关闭下拉菜单: 点击遮罩 / Esc / 窗口变化
  useEffect(() => {
    if (!menuOpen) return;
    const close = () => {
      setMenuOpen(false);
      setMenuPos(null);
    };
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') close();
    };
    window.addEventListener('keydown', onKey);
    window.addEventListener('resize', close);
    return () => {
      window.removeEventListener('keydown', onKey);
      window.removeEventListener('resize', close);
    };
  }, [menuOpen]);

  const openToolbarMenu = () => {
    const rect = menuBtnRef.current?.getBoundingClientRect();
    if (!rect) return;
    const x = Math.max(0, Math.min(rect.right - 170, window.innerWidth - 180));
    const y = Math.min(rect.bottom + 4, window.innerHeight - 160);
    setMenuPos({ x, y });
    setMenuOpen(true);
  };

  const toolbar = (
    <div className="file-tree-toolbar">
      <button className="file-tree-icon-btn" title="返回上级" disabled={currentRel === ''} onClick={goUp}>
        <ArrowUpRegular />
      </button>
      <span className="file-tree-path" title={currentRel || '/'}>
        {currentRel || '根目录'}
      </span>
      <input
        className="file-tree-search"
        type="text"
        placeholder="搜索当前目录…"
        value={query}
        onChange={(e) => setQuery(e.target.value)}
      />
      <button
        className={`file-tree-flatten-btn${flat ? ' active' : ''}`}
        title="展平当前目录"
        onClick={() => {
          setQuery('');
          setFlat((v) => !v);
        }}
      >
        展平
      </button>
      {menu ? (
        <button ref={menuBtnRef} className="file-tree-icon-btn" title="更多操作" onClick={openToolbarMenu}>
          <MoreVerticalRegular />
        </button>
      ) : null}
      {menuOpen && menu ? (
        <>
          <div
            className="context-menu-backdrop"
            onClick={() => {
              setMenuOpen(false);
              setMenuPos(null);
            }}
            onContextMenu={(e) => {
              e.preventDefault();
              setMenuOpen(false);
              setMenuPos(null);
            }}
          />
          <div className="context-menu" style={{ left: menuPos?.x ?? 0, top: menuPos?.y ?? 0 }}>
            {menu(currentAbs).map((item) => (
              <button
                key={item.key}
                className={`context-menu-item${item.danger ? ' danger' : ''}`}
                onClick={() => {
                  item.onClick();
                  setMenuOpen(false);
                  setMenuPos(null);
                }}
              >
                {item.icon}
                {item.label}
              </button>
            ))}
          </div>
        </>
      ) : null}
    </div>
  );

  const listNode = (
    <div className="file-tree-list">
      {list.length === 0 ? (
        <span className="muted">{searchResults || flatEntries ? '无匹配项' : '空目录'}</span>
      ) : searchResults || flatEntries ? (
        list.map(fileRow)
      ) : (
        list.map((node) =>
          node.isDirectory ? (
            <div
              key={node.path}
              className="file-tree-dir"
              onClick={() => enterDir(node.name)}
              onContextMenu={(e) => onItemContextMenu?.(node, e)}
              title={node.rel}
            >
              <span className="file-tree-arrow">▸</span>
              <span className="file-tree-dir-name" title={node.name}>
                {middleEllipsis(node.name, 30)}
              </span>
            </div>
          ) : (
            fileRow(node)
          )
        )
      )}
    </div>
  );

  return (
    <div className="file-tree">
      {header ? (
        header(toolbar, listNode)
      ) : (
        <>
          {toolbar}
          {listNode}
        </>
      )}
    </div>
  );
}
